CREATE TABLE livestock_marketplace_listings(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`livestock_id` bigint  NOT NULL,`farmer_id` bigint  NOT NULL,`listing_type` varchar(255)  NOT NULL COMMENT 'sale, breeding_service, milk_production',`asking_price` DECIMAL(12,2)  NOT NULL,`current_age_months` INT  NOT NULL,`current_weight_kg` DECIMAL(10,2)  NULL,`milk_production_liters_per_day` DECIMAL(10,2)  NULL COMMENT 'For dairy animals',`breeding_history` text  NULL COMMENT 'Number of successful breedings',`health_status` varchar(255)  DEFAULT 'excellent' COMMENT 'excellent, good, fair, poor',`vaccination_status` varchar(255)  DEFAULT 'up_to_date' COMMENT 'up_to_date, pending, none',`total_investment` DECIMAL(12,2)  NOT NULL COMMENT 'Purchase + feed + healthcare costs',`total_revenue` DECIMAL(12,2)  DEFAULT 0 COMMENT 'Revenue from milk, eggs, breeding',`current_roi_percentage` DECIMAL(10,2)  NULL COMMENT 'Calculated ROI percentage',`break_even_achieved` TINYINT(1)  DEFAULT 0,`break_even_date` date  NULL,`projected_annual_profit` DECIMAL(12,2)  NULL COMMENT 'AI-calculated projected profit',`location_state` varchar(255)  NOT NULL,`location_district` varchar(255)  NOT NULL,`farmer_contact_phone` varchar(255)  NOT NULL,`farmer_contact_email` varchar(255)  NULL,`listing_status` varchar(255)  DEFAULT 'active' COMMENT 'active, sold, withdrawn',`views_count` INT  DEFAULT 0,`bedrock_analysis` text  NULL COMMENT 'AI analysis of livestock value and ROI')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;